#!/bin/sh
# shellcheck disable=SC1090 # Sealed sibling selected beside the scanner helper.
CONTAINER_STABILITY_ATTEMPTS=3; CONTAINER_INVENTORY_MAX_ENTRIES=4096; CONTAINER_INVENTORY_MAX_BYTES=524288; CONTAINER_VOLUME_MAX_ENTRIES=4096; CONTAINER_VOLUME_MAX_BYTES=268435456; CONSUMER_SNAPSHOT_MAX_BYTES=67108864; case ${helper:-} in */retire-ollama-consumers.sh) consumer_closure_helper=${helper%/*}/retire-ollama-consumer-closure.sh;; *) consumer_closure_helper="$SCRIPT_DIR/retire-ollama-consumer-closure.sh";; esac; [ -f "$consumer_closure_helper" ] && [ ! -L "$consumer_closure_helper" ] || return 2; source_loader_source "$consumer_closure_helper" || return 2; CONSUMER_CLOSURE_LOADED_SHA=$SOURCE_LOADER_DIGEST
case ${helper:-} in */retire-ollama-consumers.sh) consumer_archive_helper=${helper%/*}/retire-ollama-running-archive.sh;; *) consumer_archive_helper="$SCRIPT_DIR/retire-ollama-running-archive.sh";; esac; [ -f "$consumer_archive_helper" ] && [ ! -L "$consumer_archive_helper" ] || return 2; source_loader_source "$consumer_archive_helper" || return 2; CONSUMER_ARCHIVE_LOADED_SHA=$SOURCE_LOADER_DIGEST
case ${helper:-} in */retire-ollama-consumers.sh) consumer_running_helper=${helper%/*}/retire-ollama-running-container.sh;; *) consumer_running_helper="$SCRIPT_DIR/retire-ollama-running-container.sh";; esac; [ -f "$consumer_running_helper" ] && [ ! -L "$consumer_running_helper" ] || return 2; source_loader_source "$consumer_running_helper" || return 2; CONSUMER_RUNNING_LOADED_SHA=$SOURCE_LOADER_DIGEST
consumer_hardening_named_volumes() {
  definition=$1; captured=$(consumer_snapshot "$definition") || return 2; hardening_snapshot=${captured%%|*}; hardening_identity=${captured#*|}; hardening_content=$(consumer_hash_bounded "$hardening_snapshot") || { rm -f "$hardening_snapshot"; return 2; }; definition_record="$definition|$hardening_content|$hardening_identity"; refs=$(temp_path); records=$(temp_path)
  awk 'function t(s){sub(/^[[:space:]]+/,"",s);sub(/[[:space:]]+$/, "",s);return s}function v(s){sub(/^[^:]*:[[:space:]]*/,"",s);sub(/[[:space:]]+#.*$/, "",s);return t(s)}function safe(s){return s~/^[A-Za-z0-9][A-Za-z0-9_.-]*$/}function literal(s,q){s=t(s);q=substr(s,1,1);if((q=="\""||q=="\047")&&substr(s,length(s),1)==q)s=substr(s,2,length(s)-2);return safe(s)?s:""}function emitlong(){if(!long)return;if(kind=="volume"){if(!safe(source)||target=="")bad=1;else refs[source]++}else if(kind!="bind"&&kind!="tmpfs")bad=1;long=0;kind="";source="";target="";item_indent=0}function emitdecl(){if(key=="")return;decls[key]++;if(fields[key]!="name"||!safe(names[key]))invalid[key]=1;key=""}{raw=$0;if(raw~/\t/){bad=1;next}n=raw;sub(/[^ ].*$/, "",n);n=length(n);line=raw;sub(/^[ ]*/,"",line);sub(/[[:space:]]+#.*$/, "",line);if(n==0){emitlong();emitdecl();section=(line=="services:"?"services":(line=="volumes:"?"volumes":""));svc="";inside=0;service_indent=0;volume_indent=0;declaration_indent=0;next}if(section=="services"){if(line~/^[A-Za-z0-9_.-]+:[[:space:]]*$/&&(service_indent==0||n==service_indent)&&(!inside||n<=volume_indent)){emitlong();svc=line;sub(/:.*/,"",svc);inside=0;if(service_indent==0)service_indent=n;next}if(svc!=""&&line=="volumes:"&&n>service_indent){emitlong();inside=1;volume_indent=n;next}if(inside&&n<=volume_indent){emitlong();inside=0}if(!inside)next;if(line~/^-[[:space:]]*/&&n>volume_indent){emitlong();item=line;sub(/^-[[:space:]]*/,"",item);item_indent=n;if(item~/^type:[[:space:]]*/){long=1;kind=literal(v(item));next}if(item~/^[A-Za-z0-9][A-Za-z0-9_.-]*:/){source=item;sub(/:.*/,"",source);refs[source]++;next}if(item~/\//){next}bad=1;next}if(long&&n>item_indent&&kind!="volume")next;if(long&&n>item_indent&&line~/^(source|target):[[:space:]]*/){field=line;sub(/:.*/,"",field);value=literal(v(line));if(field=="source"&&source=="")source=value;else if(field=="target"&&target=="")target=value;else bad=1;next}if(long&&n>item_indent&&line~/^read_only:[[:space:]]*(true|false)[[:space:]]*$/)next;if(long&&n>item_indent){bad=1;next}next}if(section=="volumes"){if(line~/^[A-Za-z0-9][A-Za-z0-9_.-]*:[[:space:]]*$/&&(declaration_indent==0||n==declaration_indent)){emitdecl();key=line;sub(/:.*/,"",key);fields[key]="";names[key]="";if(declaration_indent==0)declaration_indent=n;next}if(line~/^[A-Za-z0-9][A-Za-z0-9_.-]*:[[:space:]]*\{[[:space:]]*name:[[:space:]]*[A-Za-z0-9][A-Za-z0-9_.-]*[[:space:]]*\}[[:space:]]*$/&&(declaration_indent==0||n==declaration_indent)){emitdecl();key=line;sub(/:.*/,"",key);name=line;sub(/^.*name:[[:space:]]*/,"",name);sub(/[[:space:]]*\}.*$/, "",name);names[key]=name;fields[key]="name";if(declaration_indent==0)declaration_indent=n;emitdecl();next}if(key!=""&&n>declaration_indent&&line~/^[A-Za-z_][A-Za-z0-9_-]*:[[:space:]]*/){field=line;sub(/:.*/,"",field);value=literal(v(line));if(field=="name"&&fields[key]==""){names[key]=value;fields[key]="name"}else if(field=="driver"&&value=="local"){next}else invalid[key]=1;next}if(key!=""&&n>declaration_indent)invalid[key]=1} }END{emitlong();emitdecl();for(source in refs){if(refs[source]<1||decls[source]!=1||invalid[source]||!safe(names[source]))bad=1;else print source "\t" names[source]}exit bad?2:0}' "$hardening_snapshot" >"$refs" || { status=$?; rm -f "$hardening_snapshot" "$refs" "$records"; return "$status"; }
  sort -u "$refs" -o "$refs" || { rm -f "$hardening_snapshot" "$refs" "$records"; return 2; }; tab=$(printf '\t')
  while IFS="$tab" read -r logical name || [ -n "$logical$name" ]; do
    [ -n "$logical$name" ] || { rm -f "$hardening_snapshot" "$refs" "$records"; return 2; }
    raw=$(temp_path); docker --host "unix://$CANONICAL_DOCKER_SOCKET" volume inspect -f '{{json .}}' "$name" >"$raw" || { status=$?; rm -f "$hardening_snapshot" "$refs" "$records" "$raw"; return "$status"; }
    source=$(/usr/bin/jq -er --arg name "$name" 'if type == "object" and .Name == $name and .Driver == "local" and .Scope == "local" and (.Mountpoint|type)=="string" and (.Mountpoint|test("^/[A-Za-z0-9._/-]+$") and test("(^|/)\\.\\.?(/|$)")|not) then .Mountpoint else error("invalid volume") end' "$raw") || { rm -f "$hardening_snapshot" "$refs" "$records" "$raw"; return 2; }; rm -f "$raw"
    container_volume_consumers "$definition_record" "$name" "$source" "$logical" >>"$records" || { status=$?; rm -f "$hardening_snapshot" "$refs" "$records"; return "$status"; }
  done <"$refs"
  after=$(consumer_snapshot "$definition") || { rm -f "$hardening_snapshot" "$refs" "$records"; return 2; }; hardening_after_snapshot=${after%%|*}; hardening_after_identity=${after#*|}; cmp -s "$hardening_snapshot" "$hardening_after_snapshot" && [ "$hardening_identity" = "$hardening_after_identity" ] || { rm -f "$hardening_snapshot" "$refs" "$records" "$hardening_after_snapshot"; return 2; }; cat "$records"; status=$?; rm -f "$hardening_snapshot" "$refs" "$records" "$hardening_after_snapshot"; return "$status"
}
parse_systemd_words() { printf '%s\n' "$1" | awk 'BEGIN{sq=0;dq=0;esc=0;started=0;word=""}{for(i=1;i<=length($0);i++){c=substr($0,i,1);if(esc){word=word c;started=1;esc=0;continue}if(c=="\\"&&!sq){esc=1;continue}if(c=="\""&&!sq){dq=!dq;started=1;continue}if(c=="\047"&&!dq){sq=!sq;started=1;continue}if(c~/[ \t]/&&!sq&&!dq){if(started){print word;word="";started=0}continue}word=word c;started=1}}END{if(esc||sq||dq)exit 2;if(started)print word}'; }
consumer_snapshot_size() { consumer_size_record=$(stat -c '%d:%i:%f:%s:%u:%g:%a' "$1") || return 2; consumer_size_extra=''; IFS=: read -r consumer_size_device consumer_size_inode consumer_size_mode consumer_size consumer_size_uid consumer_size_gid consumer_size_permissions consumer_size_extra <<EOF
$consumer_size_record
EOF
  [ -z "$consumer_size_extra" ] || return 2; for consumer_size_field in "$consumer_size_device" "$consumer_size_inode" "$consumer_size_mode" "$consumer_size" "$consumer_size_uid" "$consumer_size_gid" "$consumer_size_permissions"; do case "$consumer_size_field" in ''|*[!0-9a-fA-F]*) return 2;; esac; done; case "$consumer_size" in ''|*[!0-9]*) return 2;; esac; [ "$consumer_size" -le "$CONSUMER_SNAPSHOT_MAX_BYTES" ] || return 2; }
consumer_hash_bounded() { /usr/bin/perl -MDigest::SHA -MFcntl=O_RDONLY,O_NOFOLLOW -e 'my($path,$limit)=@ARGV; sysopen(my$fh,$path,O_RDONLY|O_NOFOLLOW)or exit 2; my@s=stat($fh); @s&&-f _ or exit 2; binmode$fh; my$sha=Digest::SHA->new(256); my$total=0; while(1){my$read=sysread($fh,my$chunk,65536); defined$read or exit 2; last unless$read; $total+=$read; $total<=$limit or exit 2; $sha->add($chunk)} close($fh)or exit 2; print$sha->hexdigest,"\n"' "$1" "$CONSUMER_SNAPSHOT_MAX_BYTES"; }
consumer_copy_bounded() { /usr/bin/perl -MFcntl=O_RDONLY,O_NOFOLLOW,O_WRONLY,O_TRUNC -e 'my($src,$dst,$limit)=@ARGV; sysopen(my$in,$src,O_RDONLY|O_NOFOLLOW)or exit 2; my@in=stat($in); @in&&-f _ or exit 2; sysopen(my$out,$dst,O_WRONLY|O_TRUNC|O_NOFOLLOW)or exit 2; my@out=stat($out); @out&&-f _ or exit 2; binmode($in); binmode($out); my$total=0; while(1){my$read=sysread($in,my$chunk,65536); defined$read or exit 2; last unless$read; $total+=$read; $total<=$limit or exit 2; my$offset=0; while($offset<$read){my$written=syswrite($out,$chunk,$read-$offset,$offset); defined($written)&&$written>0 or exit 2; $offset+=$written}} close($in)or exit 2; close($out)or exit 2' "$1" "$2" "$CONSUMER_SNAPSHOT_MAX_BYTES"; }
consumer_source_identity() { path=$1; consumer_snapshot_size "$path" || return 2; raw=$(temp_path); { stat -c '%d:%i:%f:%s:%u:%g:%a' "$path"; findmnt -no TARGET,SOURCE,FSTYPE,OPTIONS --target "$path"; consumer_snapshot_size "$path"; consumer_hash_bounded "$path"; consumer_snapshot_size "$path"; } >"$raw" || { rm -f "$raw"; return 2; }; identity=$(consumer_hash_bounded "$raw") || { rm -f "$raw"; return 2; }; rm -f "$raw"; printf '%s\n' "$identity"; }
consumer_snapshot() { path=$1; consumer_canonical_regular "$path" >/dev/null && consumer_snapshot_size "$path" || return 2; identity=$(consumer_source_identity "$path") || return 2; consumer_snapshot_size "$path" || return 2; snapshot=$(temp_path); consumer_copy_bounded "$path" "$snapshot" || { rm -f "$snapshot"; return 2; }; consumer_snapshot_size "$path" && consumer_snapshot_size "$snapshot" && consumer_canonical_regular "$path" >/dev/null && [ "$identity" = "$(consumer_source_identity "$path")" ] || { rm -f "$snapshot"; return 2; }; printf '%s|%s\n' "$snapshot" "$identity"; }
consumer_file_fingerprint() { path=$1; captured=$(consumer_snapshot "$path") || return 2; snapshot=${captured%%|*}; identity=${captured#*|}; content=$(consumer_hash_bounded "$snapshot") || { rm -f "$snapshot"; return 2; }; printf '%s|%s|%s\n' "$path" "$content" "$identity"; status=$?; rm -f "$snapshot"; return "$status"; }
consumer_matched_fingerprint() { path=$1; captured=$(consumer_snapshot "$path") || return 2; snapshot=${captured%%|*}; identity=${captured#*|}; if consumer_matches "$snapshot"; then matched=1; else status=$?; [ "$status" -eq 1 ] || { rm -f "$snapshot"; return "$status"; }; matched=0; fi; consumer_canonical_regular "$path" >/dev/null && [ "$identity" = "$(consumer_source_identity "$path")" ] || { rm -f "$snapshot"; return 2; }; [ "$matched" -eq 1 ] || { rm -f "$snapshot"; return 1; }; content=$(consumer_hash_bounded "$snapshot") || { rm -f "$snapshot"; return 2; }; printf '%s|%s|%s\n' "$path" "$content" "$identity"; status=$?; rm -f "$snapshot"; return "$status"; }
consumer_matches() { grep -q -Ei 'ollama|11434' "$1"; }
consumer_canonical_regular() { path=$1; [ -f "$path" ] && [ ! -L "$path" ] || return 2; real=$(readlink -f -- "$path") || return 2; [ "$real" = "$path" ] && [ -f "$real" ] && [ ! -L "$real" ] || return 2; printf '%s\n' "$real"; }
nginx_include_paths() { awk '
  function include(value) { if (value == "" || value ~ /[[:space:]]/ || value ~ /(^|\/)\.\.?(\/|$)/) bad=1; else print value }
  function token(value) { if (want == 1) { include(value); want=2; return }; if (start && value == "include") { want=1; return }; start=0 }
  BEGIN { start=1; quote=""; escaped=0; value=""; comment=0 }
  { line=$0 "\n"; for (i=1; i<=length(line); i++) { c=substr(line,i,1); if (comment) { if (c=="\n") comment=0; else continue }; if (quote!="") { if (escaped) { value=value c; escaped=0; continue }; if (c=="\\") { escaped=1; continue }; if (c==quote) { token(value); value=""; quote=""; continue }; value=value c; continue }; if (c=="#") { if (value!="") { token(value); value="" }; comment=1; continue }; if (c=="\047" || c=="\"") { if (value!="") { bad=1; value="" }; quote=c; continue }; if (c ~ /[[:space:]]/) { if (value!="") { token(value); value="" }; continue }; if (c==";" || c=="{" || c=="}") { if (value!="") { token(value); value="" }; if (want==2 && c==";") want=0; else if (want!=0) bad=1; if (c!=";") start=1; else start=1; continue }; value=value c } }
  END { if (value!="") token(value); if (quote!="" || escaped || want!=0) bad=1; exit bad?2:0 }
' "$1"; }
nginx_include_pattern() { pattern=$1; case "$pattern" in /*) printf '%s|%s\n' 0 "$pattern";; *) printf '%s|%s/%s\n' 1 "$NGINX_PREFIX" "$pattern";; esac; }
nginx_prefix_target() { case "$1" in "$NGINX_PREFIX"/*) return 0;; *) return 2;; esac; }
# shellcheck disable=SC2086 # Nginx includes require deliberate pathname expansion.
nginx_linked_definition() { candidate=$1; if target=$(consumer_canonical_regular "$candidate"); then printf '%s\n' "$target"; return; fi; [ -L "$candidate" ] && nginx_prefix_target "$candidate" || return 2; target=$(readlink -f -- "$candidate") || return 2; consumer_canonical_regular "$target" >/dev/null && nginx_prefix_target "$target" || return 2; printf '%s\n' "$target"; }
scan_nginx_file() {
  caller=$(consumer_canonical_regular "$1") || return 2; grep -Fqx "$caller" "$NGINX_SEEN" >/dev/null 2>&1 && return 0; printf '%s\n' "$caller" >>"$NGINX_SEEN" || return 2
  if record=$(consumer_matched_fingerprint "$caller"); then printf '%s\n' "$record"; else status=$?; [ "$status" -eq 1 ] || return "$status"; fi
  includes=$(temp_path); nginx_include_paths "$caller" >"$includes" || { status=$?; rm -f "$includes"; return "$status"; }
  while IFS= read -r include || [ -n "$include" ]; do bound=$(nginx_include_pattern "$include") || { rm -f "$includes"; return 2; }; relative=${bound%%|*}; pattern=${bound#*|}; case "$pattern" in *'*'*|*'?'*|*'['*) wildcard=1;; *) wildcard=0;; esac; set +f; set -- $pattern; set -f; [ -e "$1" ] || { [ "$wildcard" -eq 1 ] && continue; rm -f "$includes"; return 2; }; for candidate do target=$(nginx_linked_definition "$candidate") || { rm -f "$includes"; return 2; }; [ "$relative" -eq 0 ] || nginx_prefix_target "$target" || { rm -f "$includes"; return 2; }; if target_record=$(consumer_matched_fingerprint "$target"); then definition_record=$(consumer_file_fingerprint "$caller") || { rm -f "$includes"; return 2; }; printf '%s|%s\n' "$definition_record" "$target_record"; else status=$?; [ "$status" -eq 1 ] || { rm -f "$includes"; return "$status"; }; fi; (scan_nginx_file "$target") || { status=$?; rm -f "$includes"; return "$status"; }; done; done <"$includes"; rm -f "$includes"
}
scan_nginx_definitions() { [ ! -e "$NGINX_ROOT" ] && return 0; [ -d "$NGINX_ROOT" ] && [ ! -L "$NGINX_ROOT" ] || return 2; NGINX_PREFIX=$(readlink -f -- "$NGINX_ROOT") || return 2; [ -d "$NGINX_PREFIX" ] && [ ! -L "$NGINX_PREFIX" ] || return 2; NGINX_SEEN=$(temp_path); list=$(temp_path); find "$NGINX_PREFIX" -type f >"$list" || { rm -f "$NGINX_SEEN" "$list"; return 2; }; while IFS= read -r path || [ -n "$path" ]; do scan_nginx_file "$path" || { status=$?; rm -f "$NGINX_SEEN" "$list"; return "$status"; }; done <"$list"; rm -f "$NGINX_SEEN" "$list"; }
compose_env_file_refs() {
  awk '
    function indent(s) { sub(/[^ ].*$/, "", s); return length(s) }
    function trim(s) { sub(/^[[:space:]]+/, "", s); sub(/[[:space:]]+$/, "", s); return s }
    function uncomment(s, out, i, c, prev, sq, dq, esc) {
      sq=0; dq=0; esc=0
      for (i=1; i<=length(s); i++) {
        c=substr(s, i, 1)
        if (esc) { out=out c; esc=0; prev=c; continue }
        if (c == "\\" && dq) { out=out c; esc=1; prev=c; continue }
        if (c == "\"" && !sq) { dq=!dq; out=out c; prev=c; continue }
        if (c == "\047" && !dq) { sq=!sq; out=out c; prev=c; continue }
        if (c == "#" && !sq && !dq && (i == 1 || prev ~ /[ \t]/)) return trim(out)
        out=out c; prev=c
      }
      return trim(out)
    }
    function map_field(field, key, value) {
      field=trim(field); if (field !~ /^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*:/) return 0
      key=field; sub(/[[:space:]]*:.*$/, "", key); value=field; sub(/^[^:]*:/, "", value); value=trim(value)
      if (key == "path") { if (path != "" || value == "") return 0; path=value; return 1 }
      if (key == "required") { if (required != "" || (value != "true" && value != "false")) return 0; required=value; return 1 }
      if (key == "format") { if (format != "" || (value != "default" && value != "raw")) return 0; format=value; return 1 }
      return 0
    }
    function map_fields(value, fields, count, i) { count=split(value, fields, /,/); for (i=1; i<=count; i++) if (!map_field(fields[i])) return 0; return 1 }
    function emit_map() { if (path == "") return 0; print (required == "false" ? "1:" : "0:") path; path=""; required=""; format=""; return 1 }
    function flow_maps(line, entries, count, i) {
      if (line !~ /^\[[[:space:]]*\{.*\}[[:space:]]*\]$/) return 0
      sub(/^\[[[:space:]]*\{/, "", line); sub(/\}[[:space:]]*\]$/, "", line); count=split(line, entries, /[[:space:]]*\}[[:space:]]*,[[:space:]]*\{[[:space:]]*/)
      for (i=1; i<=count; i++) { path=""; required=""; format=""; if (!map_fields(entries[i]) || !emit_map()) return 0 }; return 1
    }
    function flow_scalars(line, body, i, c, sq, dq, esc, item, count) {
      if (line !~ /^\[[[:space:]]*.*[[:space:]]*\]$/) return 0
      body=line; sub(/^\[[[:space:]]*/, "", body); sub(/[[:space:]]*\]$/, "", body); if (body == "") return 1
      sq=0; dq=0; esc=0; item=""; count=0
      for (i=1; i<=length(body); i++) { c=substr(body, i, 1); if (esc) { item=item c; esc=0; continue }; if (c == "\\" && dq) { item=item c; esc=1; continue }; if (c == "\"") { if (sq) item=item c; else { dq=!dq; item=item c }; continue }; if (c == "\047") { if (dq) item=item c; else { sq=!sq; item=item c }; continue }; if (!sq && !dq && c == ",") { item=trim(item); if (item == "") return 0; print "0:" item; count++; item=""; continue }; if (!sq && !dq && (c ~ /[\[\]\{\}]/ || c == ":")) return 0; item=item c }
      item=trim(item); if (esc || sq || dq || item == "") return 0; print "0:" item; return 1
    }
    {
      if ($0 ~ /^[[:space:]]*#/ || $0 ~ /^[[:space:]]*$/) next; n=indent($0)
      if ($0 ~ /^[[:space:]]*env_file:[[:space:]]*/) {
        line=$0; sub(/^[[:space:]]*env_file:[[:space:]]*/, "", line); line=uncomment(line); level=n
        if (line == "") { inside=1; mapped=0; path=""; required=""; format=""; next }
        if (line ~ /^\[/) { if (!flow_maps(line) && !flow_scalars(line)) bad=1; inside=0; next }
        if (line ~ /^\{/) { bad=1; next }; print "0:" line; inside=0; next
      }
      if (!inside) next
      if (n <= level) { if (mapped && !emit_map()) bad=1; inside=0; mapped=0; next }
      line=uncomment($0)
      if (line ~ /^-[[:space:]]+/) {
        if (mapped && !emit_map()) bad=1; mapped=0; path=""; required=""; format=""; sub(/^-[[:space:]]+/, "", line)
        if (line == "") { bad=1; next }
        if (line ~ /^\{.*\}$/) { sub(/^\{/, "", line); sub(/\}$/, "", line); if (!map_fields(line) || !emit_map()) bad=1; next }
        if (line ~ /^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*:/) { mapped=1; if (!map_field(line)) bad=1; next }
        if (line ~ /^[\[{]/) { bad=1; next }; print "0:" line; next
      }
      if (!mapped || !map_field(line)) bad=1
    }
    END { if (inside && mapped && !emit_map()) bad=1; exit bad ? 2 : 0 }
  ' "$1"
}
compose_env_file_path() {
  definition=$1; optional=$2; value=$3; parsed=$(temp_path); parse_systemd_words "$value" >"$parsed" || { rm -f "$parsed"; return 2; }; count=$(wc -l <"$parsed"); [ "$count" -eq 1 ] || { rm -f "$parsed"; return 2; }; IFS= read -r item <"$parsed" || { rm -f "$parsed"; return 2; }; rm -f "$parsed"
  relative=0; base=''; case "$item" in '') return 2;; /*) target=/; item=${item#/}; while [ -n "$item" ]; do part=${item%%/*}; if [ "$item" = "$part" ]; then item=''; else item=${item#*/}; fi; [ -n "$part" ] && [ "$part" != . ] || return 2; case "$target" in /) target=/$part;; *) target=$target/$part;; esac; if [ -L "$target" ]; then link=$(readlink -- "$target") || return 2; case "$target:$link" in /var:private/var|/var:/private/var|/tmp:private/tmp|/tmp:/private/tmp|/bin:usr/bin|/bin:/usr/bin|/sbin:usr/sbin|/sbin:/usr/sbin|/lib:usr/lib|/lib:/usr/lib|/lib64:usr/lib64|/lib64:/usr/lib64) :;; *) return 2;; esac; fi; done;; *'..'*) return 2;; *) relative=1; base=$(readlink -f -- "$(dirname "$definition")") || return 2; item=${item#./}; target=$base; while [ -n "$item" ]; do part=${item%%/*}; if [ "$item" = "$part" ]; then item=''; else item=${item#*/}; fi; [ -n "$part" ] && [ "$part" != . ] || return 2; target="$target/$part"; [ ! -L "$target" ] || return 2; done;; esac
